"""Regenerate the paired CPU benchmark report from checked-in raw results."""
import collections
import json
from pathlib import Path
import random
import statistics

folder = Path(__file__).resolve().parent
source = json.loads((folder / 'results.json').read_text())
rows = source['rows']

def subset(**fields):
    return [r for r in rows if all(r[k] == v for k, v in fields.items())]

def mean(group, key):
    return statistics.mean(r[key] for r in group)

def win(group):
    return f"{sum(r['cpuWin'] for r in group)}/{len(group)} ({mean(group, 'cpuWin'):.1%})"

lines = ['# CPU Planner v2 evaluation — 2026-11-07', '',
'## Result', '',
f"V2 won **{win(subset(version='v2'))}** paired campaigns; v1 won **{win(subset(version='v1'))}**. "
'This is a benchmark point estimate, not evidence of universal superiority. Zero illegal CPU recovery packages were generated by either policy. All v2 Plan saves were round-tripped and a complete campaign was replayed identically.', '',
'| Difficulty | v1 CPU wins | v2 CPU wins | v1 / v2 mean damage to player base | v1 / v2 mean damage to CPU base |',
'|---|---:|---:|---:|---:|']
for difficulty in ['easy', 'medium', 'hard']:
    old, new = [subset(version=v, difficulty=difficulty) for v in ['v1', 'v2']]
    lines.append(f"| {difficulty.title()} | {win(old)} | {win(new)} | {mean(old,'playerBaseDamage'):.1f} / {mean(new,'playerBaseDamage'):.1f} | {mean(old,'cpuBaseDamage'):.1f} / {mean(new,'cpuBaseDamage'):.1f} |")
lines += ['', '## Opponent policies', '', '| Player policy | v1 CPU wins | v2 CPU wins | v1 / v2 mean player-base damage |', '|---|---:|---:|---:|']
for policy in sorted(set(r['policy'] for r in rows)):
    old,new=[subset(version=v,policy=policy) for v in ['v1','v2']]
    lines.append(f"| {policy} | {win(old)} | {win(new)} | {mean(old,'playerBaseDamage'):.1f} / {mean(new,'playerBaseDamage'):.1f} |")
lines += ['', '## Resources, collection, and work', '', '| Metric | v1 | v2 |', '|---|---:|---:|']
for label, calc in [
    ('CPU base survives', lambda a:f"{sum(r['cpuBaseDamage']<100 for r in a)}/{len(a)}"),
    ('Mean recovered sites',lambda a:f"{mean(a,'intel'):.2f}"),
    ('Campaigns with base coordinates recovered',lambda a:str(sum(r['baseSeen'] for r in a))),
    ('Sorties recovered / launched',lambda a:f"{sum(r['recovered'] for r in a)}/{sum(r['sorties'] for r in a)} ({sum(r['recovered'] for r in a)/sum(r['sorties'] for r in a):.1%})"),
    ('Mean Logistics spent',lambda a:f"{mean(a,'spent'):.2f}"),
    ('Mean ending Logistics',lambda a:f"{mean(a,'logistics'):.2f}"),
    ('New SAMs',lambda a:str(sum(r['sams'] for r in a))),
    ('Mean marginal SAM coverage per build',lambda a:f"{sum(r['samCoverageGain'] for r in a)/max(1,sum(r['sams'] for r in a)):.3f}"),
    ('FOBs built / airborne landings at FOB / FOB strike orders',lambda a:f"{sum(r['fobs'] for r in a)} / {sum(r['fobUsed'] for r in a)} / {sum(r['fobStrikeOrders'] for r in a)}"),
    ('Mean evaluated packages per campaign',lambda a:f"{mean(a,'packages'):.1f}"),
    ('Mean counted hex expansions per campaign',lambda a:f"{mean(a,'expansions'):.1f}"),
]:
    lines.append('| '+label+' | '+' | '.join(calc(subset(version=v)) for v in ['v1','v2'])+' |')
lines += ['', 'Marginal SAM coverage is the predicted reduction in uncovered observed release-approach samples, discounting prior defenses; it is not an observed kill rate. Package and search-work counts include Adapt and Plan. V1 did not record corresponding work counters.', '', '### V2 committed intentions', '', '| Intention | Round decisions |', '|---|---:|']
for goal,n in sorted(collections.Counter(g for r in subset(version='v2') for g in r['decisions']).items()):
    lines.append(f'| {goal} | {n} |')
seeds=source['seeds']
seed_effects=[(sum(r['cpuWin'] for r in subset(seed=s,version='v2'))-sum(r['cpuWin'] for r in subset(seed=s,version='v1')))/18 for s in seeds]
rng=random.Random(42)
bootstrap=sorted(statistics.mean(rng.choices(seed_effects,k=len(seeds))) for _ in range(10000))
lines += ['', '## Method and uncertainty', '',
'432 campaigns: 12 paired seeds × six player policies × three difficulties × two CPU versions. Each runs to a legal campaign conclusion, up to six rounds, through the real fixed-tick engine. Both sides use the real new-campaign opening (two player fighters and one recon; four player assets; one CPU fighter and two-aircraft recon), 10 Logistics, three reserves, and the same rules. A legacy four-formation/decoy factory was excluded after harness validation.', '',
'V1 source is preserved under `baseline/` from `d8850a0`, with import paths redirected to shared gameplay helpers. Its planner, fixed maintenance, intelligence collection, and execution policy are retained. Both benchmark arms use the committed main strike-release validator, including movable six-unit release points. No combat odds, resources, hidden information, or force sizes were increased for v2.', '',
'Policies search public sectors until recovered intelligence authorizes strikes. Direct rush and flank emphasize forward fighter action; recon-strike searches under home cover; heavy-SAM and forward-FOB buy legal infrastructure when affordable; recon-denial keeps fighters defending home. All maintain finite aircraft through shared quotes. An infeasible order is held. These are reproducible scripts, not expert human play.', '',
f"Development seeds: {[s for s in seeds if s<100]}. Reserved evaluation seeds: {[s for s in seeds if s>=100]}. "
'Individual diagnostic tuning used development seed 3. Reserved aggregate results were observed during iterative evaluation, so they should not be treated as an untouched statistical holdout.', '',
f"Mean paired win-rate change: {statistics.mean(seed_effects)*100:+.1f} percentage points. A seed-cluster bootstrap (10,000 draws, RNG 42) gives an approximate 95% interval of {bootstrap[250]*100:+.1f} to {bootstrap[9749]*100:+.1f} points. "
'The interval is wide; do not claim statistical superiority or strict difficulty ordering. Hard approximately matches Medium here, and its v1-relative point estimate is slightly lower. Offense against heavy SAM defense remains weaker than v1 even where survival is competitive.', '',
'No FOB purchases were selected in this campaign sample. The separate behavioral gate demonstrates a previously unreachable target becoming reachable through an actual build → Transit → FOB-based strike, plus repair, trapping, and strike-caused diversion. Do not infer routine FOB use from the campaign results.', '',
'## Behavioral gates', '',
'- `src/game/cpu/cpu.test.ts`: recovered discovery-to-strike campaigns on every tier; hidden-state mutation invariance; private radar; lost collection; physical support strike; two-aircraft replacements; frozen orders; migration/reload/settlement.',
'- `src/game/cpu/infrastructure.test.ts`: legal CPU construction and payment; shared SAM firing; actual Transit basing; reload; trapping; real player strike disables an inbound destination and forces diversion; new sites remain hidden.',
'- `src/game/cpu/behavior.test.ts`: prompt weak-base strike; evidence-driven objective change; direct and both flank SAM coverage; saving; late infrastructure rejection; safer release route; advantageous suppression followed by base attack; unreachable strike unlocked by FOB; commitment; isolated economic evaluation; distant-contact distinction; useful FOB repair.', '',
'## Reproduce', '', '```sh', 'npm test', 'npm run build', 'CPU_BENCHMARK=full npm test -- Evaluation/CpuPlannerV2/benchmark.test.ts', 'python3 Evaluation/CpuPlannerV2/summarize.py', '```', '',
'No browser control or human playtest was run. Baseline fixture assertions that assumed old layout IDs, fixed strike points, guaranteed casualty-free round-three victory, or pre-existing cosmetic copy were updated to current shared mechanics. The existing build chunk-size warning remains.', '',
'## Implementation choices', '',
'- Analytic contributions and bounded spatial/purchase search; no GOAP, opponent rollout, game tree, new unit or combat rule.',
'- Conservative v1 save migration preserves committed orders until the next Plan boundary. Older absent-CPU saves retain the established one-time Medium initialization.',
'- Returned launchers provide release/payload reports; estimated target damage is kept separate from dated observed health and replaced by later observation. Unrecovered aircraft provide neither hidden target health nor exact loss coordinates.',
'- Shorter flying distance alone does not justify a FOB if the current strike is already safe and feasible. A named reachable future strike or measurable known-defense risk improvement is required, weighted by actual payload and time.',
'- Supply Depot and unsupported decoys are pruned; Maintenance Wing must repay against concrete work. No unsupported radar construction or base repair is generated.',
]
(folder/'REPORT.md').write_text('\n'.join(lines)+'\n')
